namespace Civil3DMcpPlugin;

/// <summary>A command's parameters and answer fields for listCommands {describe: true} (C221). Each parameter is
/// "name: type" with "?" for optional and a short note; written from the handlers' code (the parameter names they read
/// and the keys they answer with), not from memory. Since: the change log entry that added or last changed it.</summary>
public sealed record CommandDoc(string Since, string[] Params, string[] Returns, string? Note = null);

/// <summary>
/// C221 (2026-11-24): the described commands: those changed in F1 (C208-C221) and C189-C207. Use case: the Node schemas
